#include <zephyr/sys/mpsc_pbuf.h>

#define MPSC_PBUF_DEBUG 0

#define MPSC_PBUF_DBG(buffer, ...) do { \
	if (MPSC_PBUF_DEBUG) { \
		printk(__VA_ARGS__); \
		if (buffer) { \
			mpsc_pbuf_dump(buffer); \
		} \
	} \
} while (0)

static inline void mpsc_pbuf_dump(struct mpsc_pbuf_buffer *buffer)
{
	printk("\twr:%d/%d, rd:%d/%d, len:%d, flags:%08x\n",
		buffer->wr_idx, buffer->tmp_wr_idx,
		buffer->rd_idx, buffer->tmp_rd_idx,
		buffer->size, buffer->flags);
}

void mpsc_pbuf_init(struct mpsc_pbuf_buffer *buffer,
		    const struct mpsc_pbuf_buffer_config *cfg)
{
	int err;

	memset(buffer, 0, offsetof(struct mpsc_pbuf_buffer, buf));
	buffer->get_wlen = cfg->get_wlen;
	buffer->notify_drop = cfg->notify_drop;
	buffer->buf = cfg->buf;
	buffer->size = cfg->size;
	buffer->max_usage = 0;
	buffer->flags = cfg->flags;

	if (is_power_of_two(buffer->size)) {
		buffer->flags |= MPSC_PBUF_SIZE_POW2;
	}

	err = k_sem_init(&buffer->sem, 0, 1);
	__ASSERT_NO_MSG(err == 0);
	ARG_UNUSED(err);
}

/* Calculate free space available or till end of buffer.
 *
 * @param buffer Buffer.
 * @param[out] res Destination where free space is written.
 *
 * @retval true when space was calculated until end of buffer (and there might
 * be more space available after wrapping.
 * @retval false when space calculated cannot be contiguous any further.
 */
static inline bool free_space(struct mpsc_pbuf_buffer *buffer, uint32_t *res)
{
	if (buffer->flags & MPSC_PBUF_FULL) {
		*res = 0;
		return false;
	}

	if (buffer->rd_idx > buffer->tmp_wr_idx) {
		*res =  buffer->rd_idx - buffer->tmp_wr_idx;
		return false;
	}
	*res = buffer->size - buffer->tmp_wr_idx;

	return true;
}

/* Get amount of valid data.
 *
 * @param buffer Buffer.
 * @param[out] res Destination where available space is written.
 *
 * @retval true when space was calculated until end of buffer (and there might
 * be more space available after wrapping.
 * @retval false when space is at the end of valid space.
 */
static inline bool available(struct mpsc_pbuf_buffer *buffer, uint32_t *res)
{
	if (buffer->flags & MPSC_PBUF_FULL || buffer->tmp_rd_idx > buffer->wr_idx) {
		*res = buffer->size - buffer->tmp_rd_idx;
		return true;
	}

	*res = buffer->wr_idx - buffer->tmp_rd_idx;

	return false;
}

static inline uint32_t get_usage(struct mpsc_pbuf_buffer *buffer)
{
	uint32_t f;

	if (free_space(buffer, &f)) {
		f += (buffer->rd_idx - 1);
	}

	return buffer->size - 1 - f;
}

static inline void max_utilization_update(struct mpsc_pbuf_buffer *buffer)
{
	if (!(buffer->flags & MPSC_PBUF_MAX_UTILIZATION)) {
		return;
	}

	buffer->max_usage = MAX(buffer->max_usage, get_usage(buffer));
}

static inline bool is_valid(union mpsc_pbuf_generic *item)
{
	return item->hdr.valid;
}

static inline bool is_invalid(union mpsc_pbuf_generic *item)
{
	return !item->hdr.valid && !item->hdr.busy;
}

static inline uint32_t idx_inc(struct mpsc_pbuf_buffer *buffer,
				uint32_t idx, int32_t val)
{
	uint32_t i = idx + val;

	if (buffer->flags & MPSC_PBUF_SIZE_POW2) {
		return i & (buffer->size - 1);
	}

	return (i >= buffer->size) ? i - buffer->size : i;
}

/* Get word length of the item.
 *
 * Return length rounded up to words + 1 (if aligned stays as is).
 */
static inline uint32_t get_skip_len(union mpsc_pbuf_generic *item)
{
	return item->skip.len;
}

static void add_skip_item(struct mpsc_pbuf_buffer *buffer, uint32_t wlen)
{
	union mpsc_pbuf_generic skip = {
		.skip = { .valid = 0, .busy = 0, .len = wlen }
	};

	buffer->buf[buffer->tmp_wr_idx] = skip.raw;
	buffer->tmp_wr_idx = idx_inc(buffer, buffer->tmp_wr_idx, wlen);
	buffer->wr_idx = idx_inc(buffer, buffer->wr_idx, wlen);
	if (buffer->tmp_wr_idx == buffer->rd_idx) {
		buffer->flags |= MPSC_PBUF_FULL;
	}
}

/* Drop packet from the reader tail.
 *
 * Function starts from reading a header which gives information about item
 * status and length. Basing on status multiple actions may be taken:
 * - if item is valid and not busy formatting string is read and user is
 *   notified about dropped message, read indexes are moved forward to the
 *   next message.
 * - if item is invalid (skipped space) read indexes are moved forward.
 * - if item is busy then indexes must be moved forward for another thread
 *   to start dropping another packet. Space occupied by busy message cannot
 *   be reused now because message is concurrently processed. However, once
 *   claiming is completed we want the buffer to omit packets which may already
 *   be dropped after that. Because of that original header is replaced with
 *   an invalid packet with busy bit set and length set to the packet length.
 *   Wait until packet processing is finished (mpsc_pbuf_free), free detects
 *   situation that packet was dropped in the meantime and frees the space
 *   which was occupied by the busy packet.
 *
 * @retval true if can drop more packets.
 * @retval false if cannot drop more packets (wrap around).
 */
static bool drop_item_locked(struct mpsc_pbuf_buffer *buffer,
			     uint32_t free_wlen,
			     union mpsc_pbuf_generic *item_to_drop,
			     uint32_t *tmp_wr_idx_shift)
{
	union mpsc_pbuf_generic item;
	uint32_t rd_wlen;
	uint32_t Avail;

	(void)available(buffer, &Avail);
	if (!Avail) {
		/*Wait for wrap around*/
		return false;
	}

	item.raw = buffer->buf[buffer->tmp_rd_idx];
	rd_wlen = is_invalid(&item) ?
		get_skip_len(&item) : buffer->get_wlen(&item);

	/* Clear full flag anywhere read moves forward. */
	buffer->flags &= ~MPSC_PBUF_FULL;
	if (item.hdr.busy) {
		union mpsc_pbuf_generic *rd_item =
			(union mpsc_pbuf_generic *)&buffer->buf[buffer->tmp_rd_idx];
		/* Item is busy, cannot overwrite yet, mark as invalid (not valid)
		 * and busy, move tmp_rd_idx forward.
		 */
		MPSC_PBUF_DBG(buffer, "drop: Found busy\n");
		rd_item->skip.valid = 0;
		rd_item->skip.len = rd_wlen;
		buffer->tmp_rd_idx = idx_inc(buffer, buffer->tmp_rd_idx, rd_wlen);
		if (buffer->tmp_wr_idx == buffer->rd_idx) {
			/* No free space in the buffer, need to shift tmp_wr_idx
			 * to avoid corrupting the busy packet.
			 */
			*tmp_wr_idx_shift = rd_wlen;
		}
	} else if (is_valid(&item)) {
		/* Found valid packet, move read index and prepare item for
		 * notification.
		 */
		MPSC_PBUF_DBG(buffer, "drop: Found valid\n");
		buffer->tmp_rd_idx = idx_inc(buffer, buffer->tmp_rd_idx, rd_wlen);
		if (buffer->rd_idx == buffer->tmp_rd_idx) {
			/* Claim was not in progress. */
			buffer->rd_idx = buffer->tmp_rd_idx;
		} else {
			/* Claim was in progress, mark packet as skip packet
			 * so once claim is done this area will be skipped.
			 */
			union mpsc_pbuf_generic skip = {
				.skip = { .valid = 0, .busy = 0, .len = rd_wlen }
			};
			buffer->buf[idx_inc(buffer, buffer->tmp_rd_idx, -rd_wlen)] =
				skip.raw;
			*tmp_wr_idx_shift = rd_wlen;
		}
		*item_to_drop = item;
	} else {
		/* Found skip packet. Move read index forward. */
		MPSC_PBUF_DBG(buffer, "drop: Found skip\n");
		buffer->rd_idx = idx_inc(buffer, buffer->rd_idx, rd_wlen);
		buffer->tmp_rd_idx = idx_inc(buffer, buffer->tmp_rd_idx, rd_wlen);
	}

	/* If we wrapped around and there are no more packets to drop in this
	 * part of the buffer, add a skip packet at the end of the buffer.
	 */
	if (free_wlen) {
		add_skip_item(buffer, free_wlen);
		MPSC_PBUF_DBG(buffer, "Added skip item (len:%d)\n", free_wlen);
	}

	return true;
}

static void post_drop_action(struct mpsc_pbuf_buffer *buffer,
			     uint32_t prev_rd_idx,
			     union mpsc_pbuf_generic *item_to_drop,
			     uint32_t tmp_wr_idx_shift)
{
	if (item_to_drop->raw && buffer->notify_drop) {
		buffer->notify_drop(buffer,
			(union mpsc_pbuf_generic *)&buffer->buf[prev_rd_idx]);
	}

	if (tmp_wr_idx_shift) {
		uint32_t key = k_spin_lock(&buffer->lock);

		buffer->tmp_wr_idx = idx_inc(buffer, buffer->tmp_wr_idx,
					     tmp_wr_idx_shift);
		buffer->wr_idx = idx_inc(buffer, buffer->wr_idx,
					 tmp_wr_idx_shift);
		if (buffer->tmp_wr_idx == buffer->rd_idx) {
			buffer->flags |= MPSC_PBUF_FULL;
		}
		k_spin_unlock(&buffer->lock, key);
	}
}

void mpsc_pbuf_put_word(struct mpsc_pbuf_buffer *buffer,
			const union mpsc_pbuf_generic item)
{
	bool cont;
	uint32_t free_wlen;
	k_spinlock_key_t key;
	union mpsc_pbuf_generic dropped_item = {.raw = 0};
	uint32_t shift = 0;
	uint32_t prev_rd_idx;

	do {
		key = k_spin_lock(&buffer->lock);
		cont = free_space(buffer, &free_wlen);

		if (free_wlen) {
			buffer->buf[buffer->tmp_wr_idx] = item.raw;
			buffer->tmp_wr_idx =
				idx_inc(buffer, buffer->tmp_wr_idx, 1);
			buffer->wr_idx = idx_inc(buffer, buffer->wr_idx, 1);
			max_utilization_update(buffer);
			if (buffer->tmp_wr_idx == buffer->rd_idx) {
				buffer->flags |= MPSC_PBUF_FULL;
			}
			cont = false;
		} else if (buffer->flags & MPSC_PBUF_MODE_OVERWRITE) {
			prev_rd_idx = buffer->tmp_rd_idx;
			cont = drop_item_locked(buffer, free_wlen,
						&dropped_item, &shift);
		}
		k_spin_unlock(&buffer->lock, key);

		if (dropped_item.raw || shift) {
			post_drop_action(buffer, prev_rd_idx, &dropped_item, shift);
			dropped_item.raw = 0;
			shift = 0;
		}
	} while (cont);
}

union mpsc_pbuf_generic *mpsc_pbuf_alloc(struct mpsc_pbuf_buffer *buffer,
					 size_t wlen, k_timeout_t timeout)
{
	union mpsc_pbuf_generic *item = NULL;
	bool cont = true;
	uint32_t free_wlen;
	union mpsc_pbuf_generic dropped_item = {.raw = 0};
	uint32_t shift = 0;
	uint32_t prev_rd_idx = 0;
	bool wrap;

	MPSC_PBUF_DBG(buffer, "alloc %d words\n", (int)wlen);
	if (wlen > (buffer->size)) {
		MPSC_PBUF_DBG(buffer, "Failed to alloc\n");
		return NULL;
	}

	do {
		k_spinlock_key_t key;

		key = k_spin_lock(&buffer->lock);
		wrap = free_space(buffer, &free_wlen);

		if (free_wlen >= wlen) {
			item =
			    (union mpsc_pbuf_generic *)&buffer->buf[buffer->tmp_wr_idx];
			item->hdr.valid = 0;
			item->hdr.busy = 0;
			buffer->tmp_wr_idx =
				idx_inc(buffer, buffer->tmp_wr_idx, wlen);
			if (buffer->tmp_wr_idx == buffer->rd_idx) {
				buffer->flags |= MPSC_PBUF_FULL;
			}
			cont = false;
		} else if (wrap) {
			add_skip_item(buffer, free_wlen);
			cont = true;
		} else if ((buffer->flags & MPSC_PBUF_MODE_OVERWRITE) &&
			   (buffer->wr_idx == buffer->tmp_wr_idx)) {
			/* Dropping only allowed if there is noother alloc in
			 * progress.
			 */
			prev_rd_idx = buffer->tmp_rd_idx;
			cont = drop_item_locked(buffer, free_wlen,
						&dropped_item, &shift);
			free_wlen = 0;
		} else {
			cont = false;
		}

		k_spin_unlock(&buffer->lock, key);

		if (dropped_item.raw || shift) {
			post_drop_action(buffer, prev_rd_idx,
					 &dropped_item, shift);
			dropped_item.raw = 0;
			shift = 0;
		}

		if (!cont && !item && !K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
			int err;

			k_atexit_test();
			err = k_sem_take(&buffer->sem, timeout);
			if (err == 0) {
				cont = true;
			}
		}
	} while (cont);

	MPSC_PBUF_DBG(buffer, "alloc %p\n", item);
	if ( IS_ENABLED(CONFIG_MPSC_CLEAR_ALLOCATED) && item) {
		/* During test fill with 0xaa to simplify debugging. */
		memset(item, 0xaa, sizeof(uint32_t) * wlen);
	}

	return item;
}

void mpsc_pbuf_commit(struct mpsc_pbuf_buffer *buffer,
		       union mpsc_pbuf_generic *item)
{
	uint32_t wlen = buffer->get_wlen(item);
	k_spinlock_key_t key = k_spin_lock(&buffer->lock);

	item->hdr.valid = 1;
	buffer->wr_idx = idx_inc(buffer, buffer->wr_idx, wlen);
	max_utilization_update(buffer);
	k_spin_unlock(&buffer->lock, key);
	MPSC_PBUF_DBG(buffer, "committed %p\n", item);
}

void mpsc_pbuf_put_word_ext(struct mpsc_pbuf_buffer *buffer,
			    const union mpsc_pbuf_generic item,
			    const void *data)
{
	static const size_t l =
		(sizeof(item) + sizeof(data)) / sizeof(uint32_t);
	union mpsc_pbuf_generic *dropped_item = NULL;
	bool cont;
	uint32_t free_wlen;
	union mpsc_pbuf_generic *pitem;
	union mpsc_pbuf_generic local_item = {.raw = 0};
	uint32_t shift = 0;
	uint32_t prev_rd_idx = 0;
	bool wrap;

	do {
		k_spinlock_key_t key;

		key = k_spin_lock(&buffer->lock);
		wrap = free_space(buffer, &free_wlen);
		if (free_wlen >= l) {
			buffer->buf[buffer->tmp_wr_idx] = item.raw;
			void **p =
				(void **)&buffer->buf[buffer->tmp_wr_idx + 1];

			*p = (void *)data;
			buffer->tmp_wr_idx =
				idx_inc(buffer, buffer->tmp_wr_idx, l);
			buffer->wr_idx = idx_inc(buffer, buffer->wr_idx, l);
			max_utilization_update(buffer);
			if (buffer->tmp_wr_idx == buffer->rd_idx) {
				buffer->flags |= MPSC_PBUF_FULL;
			}
			cont = false;
		} else if (wrap) {
			add_skip_item(buffer, free_wlen);
			cont = true;
		} else if (buffer->flags & MPSC_PBUF_MODE_OVERWRITE) {
			prev_rd_idx = buffer->tmp_rd_idx;
			cont = drop_item_locked(buffer, free_wlen,
						&local_item, &shift);
			dropped_item = &local_item;
		}
		k_spin_unlock(&buffer->lock, key);

		if (local_item.raw || shift) {
			post_drop_action(buffer, prev_rd_idx, &local_item, shift);
			local_item.raw = 0;
			shift = 0;
		}
	} while (cont);
	ARG_UNUSED(pitem);
}

void mpsc_pbuf_put_data(struct mpsc_pbuf_buffer *buffer, const uint32_t *data,
			size_t wlen)
{
	bool cont;
	uint32_t free_wlen;
	union mpsc_pbuf_generic dropped_item = {.raw = 0};
	uint32_t shift = 0;
	uint32_t prev_rd_idx = 0;
	bool wrap;

	do {
		k_spinlock_key_t key;

		key = k_spin_lock(&buffer->lock);
		wrap = free_space(buffer, &free_wlen);

		if (free_wlen >= wlen) {
			memcpy(&buffer->buf[buffer->tmp_wr_idx], data,
				wlen * sizeof(uint32_t));
			buffer->wr_idx = idx_inc(buffer, buffer->wr_idx, wlen);
			buffer->tmp_wr_idx =
				idx_inc(buffer, buffer->tmp_wr_idx, wlen);
			max_utilization_update(buffer);
			if (buffer->tmp_wr_idx == buffer->rd_idx) {
				buffer->flags |= MPSC_PBUF_FULL;
			}
			cont = false;
		} else if (wrap) {
			add_skip_item(buffer, free_wlen);
			cont = true;
		} else if (buffer->flags & MPSC_PBUF_MODE_OVERWRITE) {
			prev_rd_idx = buffer->tmp_rd_idx;
			cont = drop_item_locked(buffer, free_wlen,
					     &dropped_item, &shift);
		} else {
			cont = false;
		}
		k_spin_unlock(&buffer->lock, key);

		if (dropped_item.raw || shift) {
			post_drop_action(buffer, prev_rd_idx, &dropped_item, shift);
			dropped_item.raw = 0;
			shift = 0;
		}
	} while (cont);
}

const union mpsc_pbuf_generic *mpsc_pbuf_claim(struct mpsc_pbuf_buffer *buffer)
{
	union mpsc_pbuf_generic *item;
	bool cont;
	uint32_t a;

	do {
		uint32_t wlen;
		k_spinlock_key_t key;

		cont = false;
		key = k_spin_lock(&buffer->lock);
		(void)available(buffer, &a);
		item = (union mpsc_pbuf_generic *)&buffer->buf[buffer->tmp_rd_idx];

		if (!a || is_Busy(item)) {
			MPSC_PBUF_DBG(buffer, "invalid claim %d: %p\n", a, item);
			item = NULL;
		} else {
			uint32_t skip = is_invalid(item);

			wlen = skip ? get_skip_len(item) : buffer->get_wlen(item);
			if (skip) {
				MPSC_PBUF_DBG(buffer, "skipping %d\n", wlen);
				buffer->tmp_rd_idx =
					idx_inc(buffer, buffer->tmp_rd_idx, wlen);
				buffer->rd_idx =
					idx_inc(buffer, buffer->rd_idx, wlen);
				buffer->flags &= ~MPSC_PBUF_FULL;
				cont = true;
			} else {
				item->hdr.busy = 1;
				buffer->tmp_rd_idx =
					idx_inc(buffer, buffer->tmp_rd_idx, wlen);
			}
		}
		k_spin_unlock(&buffer->lock, key);
	} while (cont);

	MPSC_PBUF_DBG(buffer, ">>claimed %d: %p\n", a, item);
	return item;
}

void mpsc_pbuf_free(struct mpsc_pbuf_buffer *buffer,
		     const union mpsc_pbuf_generic *item)
{
	union mpsc_pbuf_generic *witem = (union mpsc_pbuf_generic *)item;
	k_spinlock_key_t key = k_spin_lock(&buffer->lock);
	uint32_t wlen = witem->hdr.valid ? buffer->get_wlen(item) : witem->skip.len;

	witem->hdr.valid = 0;
	/* If packet was not dropped during claim (marked as invalid and busy)
	 * or other valid packets were not dropped during claim then move
	 * rd_idx forward.
	 */
	if (!(buffer->flags & MPSC_PBUF_MODE_OVERWRITE) ||
		((uint32_t *)item == &buffer->buf[buffer->rd_idx])) {
		buffer->rd_idx = idx_inc(buffer, buffer->rd_idx, wlen);
		if (buffer->flags & MPSC_PBUF_MODE_OVERWRITE) {
			/* Handle cases when items after just freed item were
			 * dropped while item was busy.
			 */
			witem = (union mpsc_pbuf_generic *)&buffer->buf[buffer->rd_idx];
			while ((buffer->rd_idx != buffer->tmp_rd_idx) &&
				is_invalid(witem)) {
				MPSC_PBUF_DBG(buffer, "Post free skip %d\n",
						witem->skip.len);
				buffer->rd_idx = idx_inc(buffer, buffer->rd_idx,
							 witem->skip.len);
				witem = (union mpsc_pbuf_generic *)
					&buffer->buf[buffer->rd_idx];
			}
		}
	} else {
		/* Space occurred in the middle of claimed/dropped packets.
		 * Mark it as skip to be skipped when preceding packet is freed.
		 */
		MPSC_PBUF_DBG(buffer, "Mark %p as skip (len:%d)\n", witem, wlen);
		witem->skip.len = wlen;
	}
	witem->hdr.busy = 0;

	buffer->flags &= ~MPSC_PBUF_FULL;
	MPSC_PBUF_DBG(buffer, "<<freed: %p\n", item);
	k_spin_unlock(&buffer->lock, key);
	k_sem_give(&buffer->sem);
}

bool mpsc_pbuf_is_pending(struct mpsc_pbuf_buffer *buffer)
{
	uint32_t a;

	(void)available(buffer, &a);

	return a ? true : false;
}

void mpsc_pbuf_get_utilization(struct mpsc_pbuf_buffer *buffer,
			       uint32_t *size, uint32_t *now)
{
	/* One word is reserved for full/empty distinction. */
	*size = (buffer->size - 1) * sizeof(int);
	*now = get_usage(buffer) * sizeof(int);
}

int mpsc_pbuf_get_max_utilization(struct mpsc_pbuf_buffer *buffer, uint32_t *max)
{
	if (!(buffer->flags & MPSC_PBUF_MAX_UTILIZATION)) {
		return -ENOTSUP;
	}

	*max = buffer->max_usage * sizeof(int);
	return 0;
}
